def icon(name, size=18, color=None, stroke=1.6):
    """Return an inline SVG string for the given icon key."""
    svg = ICONS.get(name)
    if not svg:
        return ""
    svg = svg.replace('width="1em" height="1em"', f'width="{size}" height="{size}"', 1)
    if stroke:
        svg = svg.replace('stroke-width="1.5"', f'stroke-width="{stroke}"')
    style = "vertical-align:middle;flex:none;display:inline-block;"
    if color:
        style += f"color:{color};"
    return svg.replace('<svg ', f'<svg style="{style}" ', 1)


def chip(name, size=18, box=36, bg="var(--chip)", color="var(--ink-soft)", radius=11):
    """Icon inside a rounded square chip — the app's signature motif."""
    return (
        f'<span style="display:inline-flex;align-items:center;justify-content:center;'
        f'width:{box}px;height:{box}px;border-radius:{radius}px;background:{bg};color:{color};'
        f'flex:none;">{icon(name, size)}</span>'
    )


def label(name, text, size=16, color=None, gap=8, weight=600):
    """Inline icon + text, vertically centered."""
    return (
        f'<span style="display:inline-flex;align-items:center;gap:{gap}px;font-weight:{weight};">'
        f'{icon(name, size, color)}<span>{text}</span></span>'
    )
